```js
// CATATAN: Mekanik urutan token belum tersedia; ide "urutan langkah" dipetakan ke kategori tahapan Bubble Sort (Perbandingan, Penukaran, Lanjut).
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "bubble-sort-runner", title: "Bubble Sort Runner", seed: "bubble-sort-01",
  theme: { preset: "neon" },

  learning: {
    subject: "Informatika / Algoritma",
    concept: "Tahapan satu putaran algoritma Bubble Sort",
    objectives: [
      "Mengenali tiga tahap inti Bubble Sort: membandingkan, menukar, dan melanjutkan",
      "Memahami bahwa pengurutan butuh banyak putaran"
    ],
    misconceptions: ["Satu putaran sudah cukup untuk mengurutkan"],
    mode: "category",
    categories: [
      { id: "perbandingan", label: "Perbandingan", color: "#00E5FF" },
      { id: "penukaran",    label: "Penukaran",    color: "#FF3DCB" },
      { id: "lanjut",       label: "Lanjut",       color: "#FFD23F" }
    ],
    items: [
      { id: "bandingkan-a",   label: "Bandingkan A[i] dan A[i+1]", category: "perbandingan", explain: "Memeriksa dua elemen bersebelahan sebelum memutuskan tukar." },
      { id: "cek-lebih",      label: "Cek A[i] > A[i+1]",          category: "perbandingan", explain: "Menentukan apakah urutan salah dan perlu ditukar." },
      { id: "tandai-posisi",  label: "Tandai posisi dibandingkan", category: "perbandingan", explain: "Mencatat pasangan yang sedang dicek dalam putaran." },
      { id: "tukar-elemen",   label: "Tukar A[i] dan A[i+1]",      category: "penukaran",    explain: "Menukar dua elemen bersebelahan yang urutannya salah." },
      { id: "simpan-sementara", label: "Simpan nilai sementara",   category: "penukaran",    explain: "Variabel bantu agar salah satu nilai tidak hilang saat ditukar." },
      { id: "letakkan-nilai", label: "Letakkan nilai ke posisi baru", category: "penukaran", explain: "Menempatkan hasil tukar ke posisi yang benar." },
      { id: "naikkan-indeks", label: "Naikkan indeks i",           category: "lanjut",       explain: "Bergerak ke pasangan berikutnya untuk dibandingkan." },
      { id: "pindah-pasangan", label: "Pindah ke pasangan berikutnya", category: "lanjut",   explain: "Melanjutkan penyusuran array ke kanan." },
      { id: "putaran-baru",   label: "Mulai putaran baru",         category: "lanjut",       explain: "Satu putaran belum tentu terurut; algoritma harus mengulang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "blok-salah", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "blok-besar", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

**Bubble Sort Runner** adalah game edukasi Endless Runner bertema Neon di mana pemain mengambil langkah-langkah Bubble Sort sesuai kategori target (Perbandingan, Penukaran, Lanjut). Asumsi penting: karena mekanik urutan token belum tersedia, konsep "urutan langkah" dipetakan ke tiga kategori tahapan algoritma.
